set -euo pipefail
if [[ $(id -u) != 0 ]]; then echo 'Run with sudo.' >&2; exit 1; fi
case "${1:-install}" in install|uninstall) ;; *) echo 'Usage: sudo bash pishield-v03.sh [install|uninstall]'; exit 2;; esac
python3 - "${1:-install}" <<'PY'
import os, sys, re, tempfile, shutil, time, subprocess
from pathlib import Path
root=Path('/var/www/html/admin')
sidebar=root/'scripts/lua/sidebar.lp'
page=root/'pishield.lp'
js=root/'scripts/js/pishield.js'
backup=Path('/var/backups/pishield')
start='<!-- PISHIELD BEGIN -->'; end='<!-- PISHIELD END -->'
marker='<!-- PiShield extension v0.'
jsmarker='// PiShield extension v0.'
pattern=re.compile(r'^[ \t]*'+re.escape(start)+r'.*?'+re.escape(end)+r'[ \t]*\n?',re.M|re.S)
anchor='<li class="header text-uppercase">Group Management</li>'
links='                <!-- PISHIELD BEGIN -->\n                <li class="header text-uppercase">PiShield</li>\n                <li><a href="<?=webhome?>pishield#overview"><i class="fa fa-fw menu-icon fa-shield-alt"></i> <span>Security overview</span></a></li>\n                <li><a href="<?=webhome?>pishield#devices"><i class="fa fa-fw menu-icon fa-network-wired"></i> <span>Device inventory</span></a></li>\n                <li><a href="<?=webhome?>pishield#activity"><i class="fa fa-fw menu-icon fa-list-ul"></i> <span>Live DNS activity</span></a></li>\n                <li><a href="<?=webhome?>pishield#health"><i class="fa fa-fw menu-icon fa-heartbeat"></i> <span>DNS health</span></a></li>\n                <li><a href="<?=webhome?>pishield-system"><i class="fa fa-fw menu-icon fa-wifi"></i> <span>Network discovery &amp; health</span></a></li>\n                <li><a href="<?=webhome?>pishield#events"><i class="fa fa-fw menu-icon fa-bell"></i> <span>Security history</span></a></li>\n                <li><a href="<?=webhome?>pishield#policies"><i class="fa fa-fw menu-icon fa-filter"></i> <span>Privacy &amp; blocklists</span></a></li>\n                <li><a href="<?=webhome?>pishield#profiles"><i class="fa fa-fw menu-icon fa-user-shield"></i> <span>Filtering profiles</span></a></li>\n                <li><a href="<?=webhome?>pishield#ai"><i class="fa fa-fw menu-icon fa-brain"></i> <span>Local AI analysis</span></a></li>\n                <!-- PISHIELD END -->\n'
html='<!-- PiShield extension v0.3 -->\n<? mg.include(\'scripts/lua/header_authenticated.lp\',\'r\') ?>\n<div id="ps-root">\n<div class="box box-solid"><div class="box-body"><button id="ps-global-refresh" class="btn btn-default btn-sm pull-right" type="button">Refresh</button><strong>PiShield v0.3</strong> · <span id="ps-global-status" role="status">Loading...</span></div></div>\n<div class="row" id="overview"><div class="col-md-12"><div class="box box-primary"><div class="box-header with-border"><h3 class="box-title">PiShield | Security overview</h3><div class="box-tools pull-right"><button id="ps-refresh" class="btn btn-default btn-sm" type="button">Refresh</button></div></div><div class="box-body">\n<p id="ps-status" role="status">Loading authenticated Pi-hole data...</p><p class="text-muted">Read-only monitoring. DNS blocks include advertising and trackers, not just threats.</p>\n<div class="row" id="ps-summary"></div>\n<h4>Recent DNS indicators</h4><p class="text-muted">Heuristics from the latest 100 recorded queries. These are investigation leads, not confirmed attacks.</p><div id="ps-alerts"></div>\n</div></div></div></div>\n<div class="row" id="devices"><div class="col-md-12"><div class="box"><div class="box-header with-border"><h3 class="box-title">Device inventory</h3></div><div class="box-body"><p id="ps-device-status" class="text-muted">Known devices from Pi-hole\'s network table; not a live connected-device census.</p><p>Click a device label to rename it or select a type. Labels are stored in this browser only. <a href="pishield-system">Open background network discovery</a>.</p><div class="form-group"><input class="form-control" id="ps-device-filter" placeholder="Filter IP, hostname, MAC or vendor" aria-label="Filter devices"></div><div class="table-responsive"><table class="table table-striped table-bordered"><thead><tr><th>Label / type</th><th>Addresses</th><th>Hostnames</th><th>MAC</th><th>Vendor</th><th>Interface</th><th>Last DNS query</th><th>Queries</th></tr></thead><tbody id="ps-devices"></tbody></table></div></div></div></div></div>\n<div class="row" id="activity"><div class="col-md-12"><div class="box"><div class="box-header with-border"><h3 class="box-title">Live DNS activity</h3></div><div class="box-body"><p class="text-muted">Latest 100 queries, refreshed every 10 seconds while this page is visible.</p><div class="form-group"><input class="form-control" id="ps-query-filter" placeholder="Filter domain, client or status" aria-label="Filter queries"></div><div class="table-responsive"><table class="table table-striped table-bordered"><thead><tr><th>Time</th><th>Client</th><th>Domain</th><th>Type</th><th>Status</th><th>Reply</th><th>Time (ms)</th></tr></thead><tbody id="ps-queries"></tbody></table></div></div></div></div></div>\n<div class="row" id="health"><div class="col-md-12"><div class="box"><div class="box-header with-border"><h3 class="box-title">DNS health</h3></div><div class="box-body"><div class="row" id="ps-health"></div><p class="text-muted">Response timing is sampled from recorded DNS replies, not a measure of internet bandwidth or network ping.</p><h4>Recent upstreams</h4><div id="ps-upstreams"></div></div></div></div></div>\n<div class="row" id="events"><div class="col-md-12"><div class="box box-primary"><div class="box-header with-border"><h3 class="box-title">Security indicator history</h3></div><div class="box-body"><p>Records heuristics observed while this dashboard is open. Stored in this browser, not a continuous intrusion detection service. Repeated indicators are grouped for 15 minutes.</p><button class="btn btn-default btn-sm" id="ps-clear-events" type="button">Clear local history</button><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Observed</th><th>Indicator</th></tr></thead><tbody id="ps-events"></tbody></table></div></div></div></div></div>\n<div class="row" id="policies"><div class="col-md-12"><div class="box box-primary"><div class="box-header with-border"><h3 class="box-title">Privacy &amp; blocklists</h3></div><div class="box-body"><p>Use Pi-hole\'s native group controls to apply lists to selected devices. No new list or policy is enabled automatically. <a href="pishield#profiles">Open filtering profiles</a>.</p><p><a class="btn btn-default" href="groups">Groups</a> <a class="btn btn-default" href="groups/clients">Clients</a> <a class="btn btn-default" href="groups/lists">Lists</a> <a class="btn btn-default" href="groups/domains">Domains</a> <a class="btn btn-default" href="settings/dns">DNS privacy</a></p><h4>Configured lists</h4><p id="ps-list-status">Loading...</p><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Address</th><th>Enabled</th><th>Comment</th><th>Groups</th></tr></thead><tbody id="ps-lists"></tbody></table></div><h4>Smart TV filtering</h4><p>Create a Smart TVs group, assign the TV client directly, and add a vetted television-specific list to that group only. If requests arrive through the router IP, per-device filtering cannot distinguish those clients. Test streaming and updates after changes.</p><h4>Family filtering</h4><p>Use a separate group and appropriate domain lists for each policy. DNS cannot enforce a complete internet schedule or prevent all encrypted DNS bypass.</p></div></div></div></div>\n<div class="row" id="profiles"><div class="col-md-12"><div class="box box-primary"><div class="box-header with-border"><h3 class="box-title">Filtering profiles &amp; parental controls</h3></div><div class="box-body">\n<p>Create a separate Pi-hole group and add a curated list to that group only. No profiles are activated on installation. Existing lists and groups are never overwritten by this tool.</p><div class="callout callout-warning"><p>Devices must use Pi-hole directly. Do not assign your router (192.168.1.1) to a device-specific group. Keep the Default group on each device to retain existing ad blocking. DNS filtering is not comprehensive parental control and cannot prevent every bypass.</p></div>\n<div class="form-group"><label for="ps-profile">Profile</label><select class="form-control" id="ps-profile"></select></div><p id="ps-profile-description"></p><p id="ps-profile-url" style="overflow-wrap:anywhere"></p><button class="btn btn-primary" id="ps-create-profile" type="button">Create group and scoped list</button> <a class="btn btn-default" href="gravity">Update Gravity</a> <a class="btn btn-default" href="groups/lists">Manage lists</a><p id="ps-profile-result" role="status" style="white-space:pre-wrap"></p>\n<h4>Assign a device</h4><p>Choose a group created above and enter the device\'s reserved IPv4 address. Existing client assignments are preserved; existing clients must be edited using native Clients. Check that the address belongs to the intended device.</p><div class="form-group"><label for="ps-profile-group">Group</label><select class="form-control" id="ps-profile-group"></select></div><div class="form-group"><label for="ps-profile-ip">Device IPv4 (192.168.1.x)</label><input id="ps-profile-ip" class="form-control" placeholder="192.168.1.x" autocomplete="off"></div><button type="button" class="btn btn-primary" id="ps-assign-profile">Assign new client</button> <a href="groups/clients" class="btn btn-default">Manage existing clients</a><p id="ps-assign-result" role="status"></p><h4>Profile status</h4><button id="ps-profile-reload" type="button" class="btn btn-default btn-sm">Reload profiles</button><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Group</th><th>Enabled</th><th>Assigned lists</th><th>Explicit clients</th></tr></thead><tbody id="ps-profile-status"></tbody></table></div><p>To undo a profile, remove its group from the client using Clients or disable the group using Groups. Changes to lists require Update Gravity. Uninstalling PiShield does not delete these native Pi-hole settings.</p></div></div></div></div>\n<div class="row" id="ai"><div class="col-md-12"><div class="box box-primary"><div class="box-header with-border"><h3 class="box-title">Local AI security analysis</h3></div><div class="box-body"><p>Analyze the latest DNS sample using a model on this browser\'s computer. The report contains counts only, not client addresses, domains, hostnames, passwords or session tokens. It is not a malware verdict and cannot modify DNS policies.</p><button id="ps-ai-prepare" type="button" class="btn btn-default">Prepare report</button> <button id="ps-ai-download" type="button" class="btn btn-default">Download prompt</button><div class="form-group"><label for="ps-ai-prompt">Report sent to local AI (preview)</label><textarea class="form-control" id="ps-ai-prompt" rows="10" readonly></textarea></div><div class="form-group"><label for="ps-ai-model">Installed local Ollama model</label><input class="form-control" id="ps-ai-model" placeholder="e.g. qwen3:4b" autocomplete="off"></div><p>Optional: Run directly against Ollama at http://127.0.0.1:11434 on this computer. Your browser or Ollama may reject cross-origin requests. Do not open Ollama to the internet; the download works without changing any Ollama settings.</p><button id="ps-ai-run" class="btn btn-primary" type="button">Analyze with local Ollama</button><p id="ps-ai-status" role="status"></p><pre id="ps-ai-output" style="white-space:pre-wrap;overflow-wrap:anywhere;color:inherit;background:transparent"></pre><p>Offline fallback: download the prompt, then in Windows PowerShell pipe its content to <code>ollama run MODEL</code>. Choose the installed model using <code>ollama list</code>.</p></div></div></div></div>\n</div>\n<script src="<?=pihole.fileversion(\'scripts/js/pishield.js\')?>"></script>\n<? mg.include(\'scripts/lua/footer.lp\',\'r\') ?>\n'
script='// PiShield extension v0.3\n(() => {\n  "use strict";\n  const el = id => document.getElementById(id);\n  const text = (id, value) => { el(id).textContent = value; };\n  const num = v => typeof v === "number" && Number.isFinite(v) ? v.toLocaleString() : "—";\n  const timestamp = t => typeof t === "number" && t > 0 ? new Date(t * 1000).toLocaleString() : "—";\n  const ms = t => typeof t === "number" && t > 0 ? (1000*t).toFixed(2) : "—";\n  let devices = [], queries = [], busy = false;\n  const storage = (key, fallback) => {try{return JSON.parse(localStorage.getItem("pishield.v2."+key))??fallback;}catch{return fallback;}};\n  function save(key,value){try{localStorage.setItem("pishield.v2."+key,JSON.stringify(value));return true;}catch{return false;}}\n  let labels=storage("labels",{}), history=storage("events",[]);\n  const sections=["overview","devices","activity","health","events","policies","profiles","ai"];\n  function view(){const current=sections.includes(location.hash.slice(1))?location.hash.slice(1):"overview";for(const id of sections){el(id).hidden=id!==current;el(id).classList.toggle("hidden",id!==current);}for(const a of document.querySelectorAll(\'.sidebar a[href*="pishield#"]\')){a.parentElement.classList.toggle("active",a.hash==="#"+current);}window.scrollTo(0,0);}\n  function renderEvents(){rows("ps-events",history.map(v=>[timestamp(v.time),v.message]),2,"No indicators observed in this browser yet.");}\n  function rememberEvents(alerts){const now=Date.now()/1000;let changed=false;for(const message of alerts){const key=message.replace(/: \\d+\\/\\d+/,": count").replace(/: \\d+ DNSSEC/,": DNSSEC");if(!history.some(v=>v.key===key&&now-v.time<900)){history.unshift({time:now,key,message});changed=true;}}if(changed){history=history.slice(0,200);save("events",history);}renderEvents();}\n\n  const blocked = s => /^(GRAVITY|REGEX|DENYLIST)(?:_CNAME)?$|^EXTERNAL_BLOCKED_|^SPECIAL_DOMAIN$/.test(s || "");\n  function node(tag, val, klass) { const n=document.createElement(tag); if(klass)n.className=klass; if(val!==undefined)n.textContent=String(val); return n; }\n  function cards(id, values) { const p=el(id); p.replaceChildren(); for(const [label,val] of values){const col=node("div",undefined,"col-lg-3 col-sm-6 col-xs-12");const card=node("div",undefined,"box box-solid box-body");card.append(node("small",label),node("h4",val));col.append(card);p.append(col);} }\n  function rows(id, values, cols, empty) {const body=el(id);body.replaceChildren();if(!values.length){const tr=node("tr"),td=node("td",empty,"text-muted");td.colSpan=cols;tr.append(td);body.append(tr);return;}for(const row of values){const tr=node("tr");for(const value of row)tr.append(node("td",value??"—"));body.append(tr);} }\n  const matches=(row,term)=>row.some(v=>String(v??"").toLowerCase().includes(term));\n  function renderDevices(){const term=el("ps-device-filter").value.toLowerCase();const body=el("ps-devices");body.replaceChildren();for(const d of devices){const key=String(d.hwaddr||d.id||"");const profile=Object.hasOwn(labels,key)?labels[key]:{};const vals=[(d.ips||[]).map(i=>i.ip).filter(Boolean).join(", "),(d.ips||[]).map(i=>i.name).filter(Boolean).join(", ")||"—",d.hwaddr,d.macVendor??d.macvendor??"—",d.interface,timestamp(d.lastQuery),num(d.numQueries)];if(!matches([profile.name,profile.type,...vals],term))continue;const tr=node("tr"),td=node("td"),b=node("button",[profile.name||"Set label",profile.type].filter(Boolean).join(" · "),"btn btn-default btn-xs");b.type="button";b.addEventListener("click",()=>{const name=prompt("Device name (empty clears name)",profile.name||"");if(name===null)return;const type=prompt("Device type: PC, Phone, TV, Router, IoT, Other",profile.type||"Other");if(type===null)return;const allowed=["PC","Phone","TV","Router","IoT","Other"];Object.defineProperty(labels,key,{value:{name:name.trim().slice(0,64),type:allowed.find(x=>x.toLowerCase()===type.trim().toLowerCase())||"Other"},enumerable:true,configurable:true,writable:true});if(!save("labels",labels))alert("Browser storage unavailable; label is temporary.");renderDevices();});td.append(b);tr.append(td);for(const v of vals)tr.append(node("td",v??"—"));body.append(tr);}if(!body.children.length)rows("ps-devices",[],8,"No matching devices reported.");}\n  function renderQueries(){const term=el("ps-query-filter").value.toLowerCase();const values=queries.map(q=>[timestamp(q.time),[q.client?.name,q.client?.ip].filter(Boolean).join(" / ")||"—",q.domain,q.type,q.status,q.reply?.type,ms(q.reply?.time)]).filter(r=>matches(r,term));rows("ps-queries",values,7,"No matching queries reported. Check privacy settings if needed.");}\n  function list(id, items, empty){const target=el(id);target.replaceChildren();if(!items.length){target.append(node("p",empty,"text-muted"));return;}const ul=node("ul");for(const item of items)ul.append(node("li",item));target.append(ul);}\n  function renderAnalysis(){const byClient=new Map(),ups=new Map();for(const q of queries){const c=q.client?.ip||"Unknown client";if(!byClient.has(c))byClient.set(c,{total:0,blocks:0,nx:0,bogus:0});const v=byClient.get(c);v.total++;if(blocked(q.status))v.blocks++;if(q.reply?.type==="NXDOMAIN"&&!blocked(q.status))v.nx++;if(q.dnssec==="BOGUS")v.bogus++;if(q.upstream)ups.set(q.upstream,(ups.get(q.upstream)||0)+1);}\n    const alerts=[];for(const [client,v] of byClient){if(v.total>=10&&v.blocks/v.total>=0.5)alerts.push(`${client}: ${v.blocks}/${v.total} queries blocked; review repeated ad/tracker or policy hits.`);if(v.nx>=8&&v.nx/v.total>=0.3)alerts.push(`${client}: ${v.nx}/${v.total} nonblocked NXDOMAIN replies; review possible failed lookups or misconfiguration.`);if(v.bogus)alerts.push(`${client}: ${v.bogus} DNSSEC BOGUS result(s); investigate validation failures.`);}\n    rememberEvents(alerts);list("ps-alerts",alerts,queries.length?"No configured indicators triggered in this sample.":"No query sample available.");\n    const times=queries.map(q=>q.reply?.time).filter(t=>typeof t==="number"&&Number.isFinite(t)&&t>0).sort((a,b)=>a-b);const percentile=p=>times.length?ms(times[Math.ceil(p*times.length)-1]):"—";cards("ps-health",[["Sample size",num(queries.length)],["Timed replies",num(times.length)],["Median (ms)",percentile(.5)],["95th percentile (ms)",percentile(.95)]]);list("ps-upstreams",[...ups].sort((a,b)=>b[1]-a[1]).map(([k,v])=>`${k}: ${v} recorded queries`),"No upstream destinations in the sample.");}\n  function request(path){return new Promise((resolve,reject)=>{const csrf=document.querySelector(\'meta[name="csrf-token"]\')?.content;const base=document.body.dataset.apiurl;if(!base){reject(new Error("API URL unavailable"));return;}const url=new URL(base+path,location.href);if(url.origin!==location.origin){reject(new Error("Unexpected API origin"));return;}const headers=csrf?{"X-CSRF-TOKEN":csrf}:{};$.ajax({url:url.href,dataType:"json",method:"GET",headers,cache:false,timeout:8000}).done(resolve).fail((xhr)=>reject(new Error(`HTTP ${xhr.status||"unavailable"}`)));});}\n  async function refresh(){if(busy||document.hidden)return;busy=true;el("ps-refresh").disabled=true;el("ps-global-refresh").disabled=true;try{const [s,d,q]=await Promise.allSettled([request("/stats/summary"),request("/network/devices?max_devices=256&max_addresses=12"),request("/queries?length=100")]);const failures=[];if(s.status==="fulfilled"&&s.value.queries){const a=s.value;cards("ps-summary",[["Total DNS queries",num(a.queries.total)],["Blocked queries",num(a.queries.blocked)],["Blocked percentage",typeof a.queries.percent_blocked==="number"?a.queries.percent_blocked.toFixed(1)+"%":"—"],["Active clients",num(a.clients?.active)]]);}else{cards("ps-summary",[["Summary","Unavailable"]]);failures.push("summary");}\n    if(d.status==="fulfilled"&&Array.isArray(d.value.devices)){devices=d.value.devices;text("ps-device-status",`${devices.length} known device records returned (maximum 256). Not a live connected-device census.`);}else{devices=[];text("ps-device-status","Device API unavailable.");failures.push("devices");}renderDevices();\n    if(q.status==="fulfilled"&&Array.isArray(q.value.queries)){queries=q.value.queries;}else{queries=[];failures.push("queries");}renderQueries();renderAnalysis();text("ps-status",failures.length?`Unavailable: ${failures.join(", ")}. Check login/API permissions; retry Refresh.`:`Updated ${new Date().toLocaleTimeString()} · automatic refresh enabled`);\n  text("ps-global-status",el("ps-status").textContent);if(location.hash==="#policies")await refreshLists();\n  }catch(e){text("ps-status","Unable to refresh: "+e.message);text("ps-global-status",el("ps-status").textContent);}finally{busy=false;el("ps-refresh").disabled=false;el("ps-global-refresh").disabled=false;}}\n  async function refreshLists(){try{const data=await request("/lists");if(!Array.isArray(data.lists))throw new Error("Unrecognized list response");rows("ps-lists",data.lists.map(v=>[v.address,v.enabled===true||v.enabled===1?"Yes":v.enabled===false||v.enabled===0?"No":"—",v.comment,Array.isArray(v.groups)?v.groups.join(", "):"—"]),4,"No lists configured.");text("ps-list-status",`${data.lists.length} configured lists. Edit using native Lists.`);}catch(e){text("ps-list-status","List API unavailable: "+e.message);rows("ps-lists",[],4,"Open native Lists to manage subscriptions.");}}\n    const profiles=[\n    {name:"PiShield Smart TVs",desc:"Standard TV advertising and telemetry filtering; test streaming, updates and sign-in after enabling.",url:"https://raw.githubusercontent.com/PCTestAdmin/tv-blocklist/main/lists/hosts.txt"},\n    {name:"PiShield Family",desc:"Adult-content blocking for selected devices; not a substitute for device-level parental controls. This list may be large.",url:"https://cdn.jsdelivr.net/gh/hagezi/dns-blocklists@latest/wildcard/nsfw-onlydomains.txt"},\n    {name:"PiShield Security",desc:"Size-optimized threat feed covering known malicious and phishing domains; false positives remain possible.",url:"https://cdn.jsdelivr.net/gh/hagezi/dns-blocklists@latest/wildcard/tif.mini-onlydomains.txt"},\n    {name:"PiShield Gambling",desc:"Gambling-site filtering for selected devices; mini list for lower resource usage.",url:"https://cdn.jsdelivr.net/gh/hagezi/dns-blocklists@latest/wildcard/gambling.mini-onlydomains.txt"}\n  ];\n  const profileComment="PiShield v0.3 scoped profile";\n  let profileBusy=false, profileData=null;\n  function writeRequest(path,data){return new Promise((resolve,reject)=>{const csrf=document.querySelector(\'meta[name="csrf-token"]\')?.content,base=document.body.dataset.apiurl;if(!csrf||!base){reject(new Error("Missing native authenticated API context"));return;}const u=new URL(base+path,location.href);if(u.origin!==location.origin){reject(new Error("Unexpected API origin"));return;}$.ajax({url:u.href,method:"POST",dataType:"json",contentType:"application/json; charset=utf-8",processData:false,data:JSON.stringify(data),headers:{"X-CSRF-TOKEN":csrf,"X-FTL-CSRF":csrf},timeout:15000}).done(resolve).fail(xhr=>reject(new Error(`HTTP ${xhr.status||"unavailable"}: ${xhr.responseJSON?.error?.message||"request failed"}`)));});}\n  async function getProfiles(){const [g,l,c]=await Promise.all([request("/groups"),request("/lists"),request("/clients")]);if(!Array.isArray(g.groups)||!Array.isArray(l.lists)||!Array.isArray(c.clients))throw new Error("Unrecognized profile API response");return {groups:g.groups,lists:l.lists,clients:c.clients};}\n  const hasGroup=(item,id)=>Array.isArray(item.groups)&&item.groups.includes(id);\n  const isEnabled=v=>v===true||v===1;\n  function renderProfileStatus(data){profileData=data;const groups=data.groups.filter(g=>profiles.some(p=>p.name===g.name)&&g.comment===profileComment&&Number.isInteger(g.id)&&g.id>0);const select=el("ps-profile-group"),previous=select.value;select.replaceChildren();for(const g of groups.filter(g=>isEnabled(g.enabled))){const o=node("option",g.name);o.value=String(g.id);select.append(o);}if([...select.options].some(o=>o.value===previous))select.value=previous;rows("ps-profile-status",groups.map(g=>[g.name,isEnabled(g.enabled)?"Yes":"No",data.lists.filter(l=>hasGroup(l,g.id)).length,data.clients.filter(c=>hasGroup(c,g.id)).length]),4,"No managed profiles created yet.");}\n  async function reloadProfiles(){try{renderProfileStatus(await getProfiles());}catch(e){profileData=null;el("ps-profile-group").replaceChildren();rows("ps-profile-status",[],4,"Profile API unavailable: "+e.message);}}\n  function selectedProfile(){return profiles[Number(el("ps-profile").value)]||profiles[0];}\n  function describeProfile(){const p=selectedProfile();text("ps-profile-description",p.desc);text("ps-profile-url",p.url);}\n  async function createProfile(){if(profileBusy)return;const p=selectedProfile();if(!confirm(`Create or complete ${p.name} with this list? Existing subscriptions are not changed. No new clients are assigned automatically.`))return;profileBusy=true;el("ps-create-profile").disabled=true;el("ps-assign-profile").disabled=true;try{let data=await getProfiles();let group=data.groups.find(g=>g.name===p.name);if(group&&group.comment!==profileComment)throw new Error("Group name already exists and is not owned by PiShield. Use native Groups.");const existing=data.lists.find(l=>l.address===p.url);if(existing&&(!group||!hasGroup(existing,group.id)))throw new Error("This list already exists. Use native Lists to add the group without changing other assignments.");if(!group){await writeRequest("/groups",{name:[p.name],comment:profileComment,enabled:true});data=await getProfiles();group=data.groups.find(g=>g.name===p.name&&g.comment===profileComment);}if(!group||!Number.isInteger(group.id)||group.id<=0||!isEnabled(group.enabled))throw new Error("Could not verify enabled non-default group; check native Groups.");if(!existing){await writeRequest("/lists?type=block",{address:[p.url],comment:p.name,groups:[group.id]});}data=await getProfiles();const list=data.lists.find(l=>l.address===p.url&&hasGroup(l,group.id)&&l.type!=="allow");if(!list)throw new Error("List assignment not confirmed; inspect native Lists.");renderProfileStatus(data);text("ps-profile-result",`${p.name}: group and list verified. ${isEnabled(list.enabled)?"List enabled.":"List disabled; review native Lists."} Open Update Gravity, then assign a device. If the group already has clients, refreshing Gravity may affect them.`);}catch(e){text("ps-profile-result","Stopped: "+e.message+". Any completed group/list creation is retained; retry or review native Groups and Lists.");await reloadProfiles();}finally{profileBusy=false;el("ps-create-profile").disabled=false;el("ps-assign-profile").disabled=false;}}\n  function eligibleIp(ip){const m=/^192\\.168\\.1\\.([1-9]\\d{0,2})$/.exec(ip);return !!m&&Number(m[1])>=2&&Number(m[1])<=254&&Number(m[1])!==106;}\n  async function assignProfile(){if(profileBusy)return;const ip=el("ps-profile-ip").value.trim(),id=Number(el("ps-profile-group").value);if(!eligibleIp(ip)||!Number.isInteger(id)||id<=0){text("ps-assign-result","Select a profile and enter a valid device address, not the router or Pi.");return;}if(!confirm(`Assign ${ip} to the selected profile while keeping Default? Confirm it is the correct device and uses Pi-hole directly.`))return;profileBusy=true;el("ps-create-profile").disabled=true;el("ps-assign-profile").disabled=true;try{const data=await getProfiles();const group=data.groups.find(g=>g.id===id&&g.comment===profileComment&&isEnabled(g.enabled)&&profiles.some(p=>p.name===g.name));if(!group)throw new Error("Group no longer available");const p=profiles.find(p=>p.name===group.name);if(!data.lists.some(l=>l.address===p.url&&hasGroup(l,id)&&isEnabled(l.enabled)))throw new Error("No enabled profile list assigned");if(data.clients.some(c=>c.client===ip))throw new Error("Client exists; edit its group assignments in native Clients instead");await writeRequest("/clients",{client:[ip],comment:"PiShield profile",groups:[0,id]});const after=await getProfiles();if(!after.clients.some(c=>c.client===ip&&hasGroup(c,id)&&hasGroup(c,0)))throw new Error("Assignment not verified; check native Clients");renderProfileStatus(after);text("ps-assign-result",`Assigned ${ip} to Default and ${group.name}. Check Query Log for direct client traffic.`);}catch(e){text("ps-assign-result","Stopped: "+e.message);}finally{profileBusy=false;el("ps-create-profile").disabled=false;el("ps-assign-profile").disabled=false;}}\n  function prepareAI(){const q=queries.slice(0,100);if(!q.length){el("ps-ai-prompt").value="";text("ps-ai-status","No DNS sample available. Refresh first.");return false;}const times=q.map(v=>v.reply?.time).filter(v=>typeof v==="number"&&Number.isFinite(v)&&v>=0).sort((a,b)=>a-b);const summary={sample_size:q.length,blocked:q.filter(v=>blocked(v.status)).length,nonblocked_nxdomain:q.filter(v=>!blocked(v.status)&&v.reply?.type==="NXDOMAIN").length,dnssec_bogus:q.filter(v=>v.dnssec==="BOGUS").length,distinct_reported_clients:new Set(q.map(v=>v.client?.ip).filter(Boolean)).size,median_reply_ms:times.length?Math.round(times[Math.floor((times.length-1)/2)]*100000)/100:null};el("ps-ai-prompt").value="You are a defensive home DNS analyst. Explain this aggregate sample, distinguish ordinary ads and failed lookups from evidence of compromise, suggest low-risk diagnostic checks, and state limitations. Never assume blocked queries are malware. No automatic actions.\\n\\n"+JSON.stringify(summary,null,2);text("ps-ai-status","Aggregate report prepared. Review before sending.");return true;}\n  function downloadAI(){if(!el("ps-ai-prompt").value&&!prepareAI())return;const url=URL.createObjectURL(new Blob([el("ps-ai-prompt").value],{type:"text/plain"}));const a=node("a");a.href=url;a.download="pishield-ai-report.txt";document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}\n  async function runAI(){const prompt=el("ps-ai-prompt").value,model=el("ps-ai-model").value.trim();if(!prompt||!/^[a-zA-Z0-9][a-zA-Z0-9._:/-]{0,99}$/.test(model)){text("ps-ai-status","Prepare a report and enter an installed model name first.");return;}if(!confirm("Send the displayed aggregate report to Ollama on this computer (127.0.0.1)?"))return;const button=el("ps-ai-run");button.disabled=true;text("ps-ai-output","");text("ps-ai-status","Waiting for local Ollama...");const ac=new AbortController(),timer=setTimeout(()=>ac.abort(),120000);try{const res=await fetch("http://127.0.0.1:11434/api/generate",{method:"POST",credentials:"omit",headers:{"Content-Type":"application/json"},body:JSON.stringify({model,prompt,stream:false,options:{num_predict:500}}),signal:ac.signal});if(!res.ok)throw new Error("HTTP "+res.status);const data=await res.json();if(typeof data.response!=="string")throw new Error("Unexpected response");text("ps-ai-output",data.response);text("ps-ai-status","Local analysis complete. Review independently; no settings were changed.");}catch(e){text("ps-ai-status","Local AI unavailable: "+e.message+". Download the prompt and run Ollama in PowerShell instead.");}finally{clearTimeout(timer);button.disabled=false;}}\n  function initV3(){const s=el("ps-profile");profiles.forEach((p,i)=>{const o=node("option",p.name);o.value=String(i);s.append(o);});describeProfile();s.addEventListener("change",describeProfile);el("ps-create-profile").addEventListener("click",createProfile);el("ps-assign-profile").addEventListener("click",assignProfile);el("ps-profile-reload").addEventListener("click",reloadProfiles);el("ps-ai-prepare").addEventListener("click",prepareAI);el("ps-ai-download").addEventListener("click",downloadAI);el("ps-ai-run").addEventListener("click",runAI);if(location.hash==="#profiles")reloadProfiles();}\n\n  function init(){if(!el("ps-root"))return;view();renderEvents();initV3();window.addEventListener("hashchange",()=>{view();if(location.hash==="#policies")refreshLists();if(location.hash==="#profiles")reloadProfiles();});el("ps-global-refresh").addEventListener("click",refresh);el("ps-clear-events").addEventListener("click",()=>{if(confirm("Clear PiShield local indicator history?")){history=[];save("events",history);renderEvents();}});el("ps-refresh").addEventListener("click",refresh);el("ps-device-filter").addEventListener("input",renderDevices);el("ps-query-filter").addEventListener("input",renderQueries);document.addEventListener("visibilitychange",()=>{if(!document.hidden)refresh();});setTimeout(refresh,100);setInterval(refresh,10000);}\n  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init();\n})();\n'
systempage=root/'pishield-system.lp'
collectorpath=Path('/opt/pishield/collector.py')
unitroot=Path('/etc/systemd/system')
state=Path('/var/lib/pishield')
units={unitroot/'pishield-collect.service':'# PiShield extension v0.2\n[Unit]\nDescription=PiShield local network and health collection\nAfter=network-online.target\n[Service]\nType=oneshot\nExecStart=/usr/bin/python3 /opt/pishield/collector.py collect\nTimeoutStartSec=90\nUMask=0077\nNoNewPrivileges=true\nPrivateTmp=true\nProtectHome=true\nProtectSystem=strict\nReadWritePaths=/var/lib/pishield /var/www/html/admin\n',unitroot/'pishield-collect.timer':'# PiShield extension v0.2\n[Unit]\nDescription=PiShield local discovery every five minutes\n[Timer]\nOnBootSec=30s\nOnUnitActiveSec=5min\nAccuracySec=10s\n[Install]\nWantedBy=timers.target\n',unitroot/'pishield-backup.service':'# PiShield extension v0.2\n[Unit]\nDescription=PiShield daily configuration snapshot\n[Service]\nType=oneshot\nExecStart=/usr/bin/python3 /opt/pishield/collector.py backup\nTimeoutStartSec=120\nUMask=0077\nNoNewPrivileges=true\nPrivateTmp=true\nProtectHome=true\nProtectSystem=strict\nReadWritePaths=/var/backups/pishield /etc/pihole\n',unitroot/'pishield-backup.timer':'# PiShield extension v0.2\n[Unit]\nDescription=PiShield daily configuration backup\n[Timer]\nOnCalendar=daily\nPersistent=true\n[Install]\nWantedBy=timers.target\n'}
extra={systempage:'<!-- PiShield extension v0.2 system -->\n<? mg.include(\'scripts/lua/header_authenticated.lp\',\'r\') ?>\n<div class="box box-primary"><div class="box-header with-border"><h3 class="box-title">Network discovery &amp; health</h3></div><div class="box-body"><p>No background sample collected yet. Refresh this page after the first scan completes.</p><p><a class="btn btn-default" href="pishield-system">Refresh snapshot</a></p></div></div>\n<? mg.include(\'scripts/lua/footer.lp\',\'r\') ?>\n',collectorpath:'#!/usr/bin/python3\n# PiShield v0.2 collector. Local IPv4 discovery and connection health only.\nimport concurrent.futures, datetime, html, ipaddress, json, os, pathlib, re, shutil, sqlite3, subprocess, sys, tempfile, time\nSTATE=pathlib.Path(\'/var/lib/pishield\')\nWEB=pathlib.Path(\'/var/www/html/admin/pishield-system.lp\')\nBACKUP=pathlib.Path(\'/var/backups/pishield/daily\')\nMARK=\'<!-- PiShield extension v0.2 system -->\'\ndef atomic(p,s,mode=0o600):\n    fd,tmp=tempfile.mkstemp(dir=p.parent,prefix=\'.pishield-\')\n    try:\n        with os.fdopen(fd,\'w\') as f: f.write(s)\n        os.chmod(tmp,mode); os.replace(tmp,p)\n    finally:\n        if os.path.exists(tmp): os.unlink(tmp)\ndef run(args,timeout=6):\n    try:\n        p=subprocess.run(args,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,text=True,timeout=timeout,env={**os.environ,\'LC_ALL\':\'C\'})\n        return p.returncode,p.stdout\n    except (OSError,subprocess.TimeoutExpired): return 1,\'\'\ndef read_json(p,default):\n    try: return json.loads(p.read_text())\n    except (OSError,ValueError): return default\ndef ping(addr,count=1):\n    rc,s=run([\'ping\',\'-n\',\'-I\',\'wlan0\',\'-c\',str(count),\'-W\',\'1\',str(addr)],count+4)\n    loss=re.search(r\'([\\d.]+)% packet loss\',s)\n    rtt=re.search(r\'= [\\d.]+/([\\d.]+)/\',s)\n    return {\'loss\':float(loss[1]) if loss else None,\'ms\':float(rtt[1]) if rtt else None,\'reply\':rc==0 or bool(rtt)}\ndef local_network():\n    rc,s=run([\'ip\',\'-j\',\'-4\',\'addr\',\'show\',\'dev\',\'wlan0\'])\n    if rc: return None,None\n    for interface in json.loads(s):\n        for a in interface.get(\'addr_info\',[]):\n            if a.get(\'scope\')==\'global\':\n                i=ipaddress.IPv4Interface(f"{a[\'local\']}/{a[\'prefixlen\']}")\n                # Only the explicitly authorized home subnet. Never scan a routed or public network.\n                if i.network==ipaddress.IPv4Network(\'192.168.1.0/24\'): return i.ip,i.network\n    return None,None\ndef stamp(t): return datetime.datetime.fromtimestamp(t).astimezone().strftime(\'%Y-%m-%d %H:%M:%S %Z\')\ndef esc(v): return html.escape(str(v),quote=True)\ndef table(headers,rows):\n    return \'<div class="table-responsive"><table class="table table-striped table-bordered"><thead><tr>\'+\'\'.join(\'<th>\'+esc(h)+\'</th>\' for h in headers)+\'</tr></thead><tbody>\'+\'\'.join(\'<tr>\'+\'\'.join(\'<td>\'+esc(v if v is not None else \'—\')+\'</td>\' for v in r)+\'</tr>\' for r in rows)+\'</tbody></table></div>\'\ndef box(title,body): return \'<div class="box box-primary"><div class="box-header with-border"><h3 class="box-title">\'+esc(title)+\'</h3></div><div class="box-body">\'+body+\'</div></div>\'\ndef collect():\n    STATE.mkdir(mode=0o700,exist_ok=True)\n    if not WEB.is_file() or not WEB.read_text().startswith(MARK): raise RuntimeError(\'PiShield system page missing or not owned; rerun installer.\')\n    now=time.time(); own,network=local_network(); observed=[]; replies=set()\n    if network:\n        hosts=[str(h) for h in network.hosts() if h!=own]\n        with concurrent.futures.ThreadPoolExecutor(max_workers=24) as pool:\n            for addr,result in zip(hosts,pool.map(ping,hosts)):\n                if result[\'reply\']: replies.add(addr)\n        rc,s=run([\'ip\',\'-j\',\'-4\',\'neigh\',\'show\',\'dev\',\'wlan0\'])\n        neighbors={}\n        if not rc:\n            for n in json.loads(s):\n                try:\n                    if ipaddress.IPv4Address(n[\'dst\']) not in network: continue\n                except (KeyError,ValueError): continue\n                if not n.get(\'lladdr\'): continue\n                status=n.get(\'state\',[]); status=status if isinstance(status,list) else [status]\n                if \'FAILED\' in status or \'INCOMPLETE\' in status: continue\n                neighbors[n[\'dst\']]=(n[\'lladdr\'],\',\'.join(status))\n        for addr in sorted(set(neighbors)|replies,key=ipaddress.IPv4Address):\n            mac,status=neighbors.get(addr,(\'—\',\'—\'))\n            observed.append((addr,mac,\'Ping reply\' if addr in replies else \'Neighbor cache only\',status))\n    gateway=None\n    rc,s=run([\'ip\',\'-j\',\'-4\',\'route\',\'show\',\'default\',\'dev\',\'wlan0\'])\n    if not rc:\n        for route in json.loads(s):\n            if route.get(\'gateway\')==\'192.168.1.1\': gateway=route[\'gateway\'];break\n    gw=ping(gateway,3) if gateway else {\'loss\':None,\'ms\':None}\n    ext=ping(\'9.9.9.9\',3) if network else {\'loss\':None,\'ms\':None}\n    rc,wifi=run([\'iw\',\'dev\',\'wlan0\',\'link\']); sig=re.search(r\'signal:\\s*(-?\\d+)\\s*dBm\',wifi); signal=int(sig[1]) if sig else None\n    history=read_json(STATE/\'health.json\',[])\n    history=(history+[{\'time\':now,\'gw\':gw,\'ext\':ext,\'signal\':signal}])[-288:]\n    atomic(STATE/\'health.json\',json.dumps(history))\n    def fmt(x,unit): return \'—\' if x is None else f\'{x:g} {unit}\'\n    hr=[[stamp(r[\'time\']),fmt(r[\'gw\'][\'ms\'],\'ms\'),fmt(r[\'gw\'][\'loss\'],\'%\'),fmt(r[\'ext\'][\'ms\'],\'ms\'),fmt(r[\'ext\'][\'loss\'],\'%\'),fmt(r[\'signal\'],\'dBm\')] for r in reversed(history[-24:])]\n    # Native authenticated page; never place raw logs, configuration, credentials or JSON under webroot.\n    nav=\'<p><a class="btn btn-default" href="pishield#overview">Security overview</a> <a class="btn btn-default" href="pishield-system">Refresh snapshot</a></p>\'\n    body=nav+box(\'Network discovery\',f\'<p>Last sample: {esc(stamp(now))}. Automatic local scan about every five minutes. Scope: 192.168.1.0/24 on wlan0 only.</p><p>{len(replies)} ping replies; {len(observed)} observed addresses including neighbor-cache entries. Cache entries are not proof a device is online. Sleeping devices, client isolation and firewalls can hide devices.</p>\'+ (table([\'IPv4\',\'MAC\',\'Evidence\',\'Neighbor state\'],observed) if observed else \'<p>No visible peers or configured subnet unavailable.</p>\'))\n    body+=box(\'Connection health\',\'<p>Gateway and Quad9 ICMP samples, three probes each. No response can mean ICMP filtering, not necessarily an internet outage. This is not a speed test. Latest 24 samples shown; up to 288 retained.</p>\'+table([\'Time\',\'Gateway RTT\',\'Gateway loss\',\'Quad9 RTT\',\'Quad9 loss\',\'Wi-Fi signal\'],hr))\n    bks=sorted(BACKUP.glob(\'snapshot-*\'),reverse=True) if BACKUP.exists() else []\n    body+=box(\'Configuration backups\',\'<p>Daily root-only copies of Pi-hole settings, gravity database and PiShield web files. Retains seven successful snapshots. Does not back up query history. Use Pi-hole Teleporter for its supported portable export/restore.</p><p>Latest snapshot: \'+esc(bks[0].name if bks else \'No successful backup yet\')+\'</p><p><a class="btn btn-default" href="settings/teleporter">Open Teleporter</a></p>\')\n    atomic(WEB,MARK+"\\n<? mg.include(\'scripts/lua/header_authenticated.lp\',\'r\') ?>\\n"+body+"\\n<? mg.include(\'scripts/lua/footer.lp\',\'r\') ?>\\n",0o644)\ndef backup():\n    BACKUP.mkdir(mode=0o700,parents=True,exist_ok=True); BACKUP.chmod(0o700)\n    temp=pathlib.Path(tempfile.mkdtemp(prefix=\'.snapshot-\',dir=BACKUP)); dest=BACKUP/(\'snapshot-\'+time.strftime(\'%Y%m%d-%H%M%S\'))\n    try:\n        source=pathlib.Path(\'/etc/pihole\'); shutil.copy2(source/\'pihole.toml\',temp/\'pihole.toml\')\n        for name in [\'hosts\',\'dhcp.leases\']:\n            p=source/name\n            if p.is_dir(): shutil.copytree(p,temp/name)\n            elif p.is_file(): shutil.copy2(p,temp/name)\n        with sqlite3.connect(\'file:/etc/pihole/gravity.db?mode=ro\',uri=True,timeout=15) as src, sqlite3.connect(temp/\'gravity.db\') as dst: src.backup(dst)\n        web=WEB.parent\n        for name in [\'pishield.lp\',\'scripts/js/pishield.js\',\'scripts/lua/sidebar.lp\']:\n            p=web/name\n            if p.is_file(): shutil.copy2(p,temp/p.name)\n        temp.rename(dest)\n    except BaseException:\n        shutil.rmtree(temp,ignore_errors=True); raise\n    for p in sorted(BACKUP.glob(\'snapshot-*\'),reverse=True)[7:]:\n        if p.is_dir() and not p.is_symlink(): shutil.rmtree(p)\n    print(\'Backup:\',dest)\nif __name__==\'__main__\':\n    if sys.argv[1:]==[\'backup\']: backup()\n    elif sys.argv[1:]==[\'collect\']: collect()\n    else: sys.exit(\'Specify collect or backup\')\n',**units}
timers=['pishield-collect.timer','pishield-backup.timer']
services=['pishield-collect.service','pishield-backup.service']
def ctl(*args,check=True):
    return subprocess.run(['systemctl',*args],check=check)
def is_active(name):
    return subprocess.run(['systemctl','is-active','--quiet',name]).returncode==0
def is_enabled(name):
    return subprocess.run(['systemctl','is-enabled','--quiet',name],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL).returncode==0

def atomic(p, data):
    fd,tmp=tempfile.mkstemp(prefix='.pishield-',dir=p.parent)
    try:
        with os.fdopen(fd,'w',encoding='utf8') as f: f.write(data)
        os.chmod(tmp,0o644); os.replace(tmp,p)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)
def read(p): return p.read_text(encoding='utf8')
def owned(p,m): return not p.exists() or read(p).startswith(m)
if not sidebar.is_file(): sys.exit('Pi-hole sidebar not found. No changes made.')
original=read(sidebar)
if original.count(start)!=original.count(end) or original.count(start)>1: sys.exit('Unexpected existing patch markers. No changes made.')
clean=pattern.sub('',original)
if start in clean or end in clean: sys.exit('Malformed patch. No changes made.')
if page.is_symlink() or js.is_symlink() or sidebar.is_symlink() or not owned(page,marker) or not owned(js,jsmarker): sys.exit('File name conflict. No changes made.')
for p in extra:
    prefix = '<!-- PiShield extension v0.2 system -->' if p==systempage else '#!/usr/bin/python3\n# PiShield v0.2 collector' if p==collectorpath else '# PiShield extension v0.2'
    if p.is_symlink() or not owned(p,prefix): sys.exit(f'File conflict: {p}. No changes made.')
if sys.argv[1]=='uninstall':
    for name in timers: ctl('disable','--now',name,check=False)
    for name in services: ctl('stop',name,check=False)
    for p in extra:
        if p.exists(): p.unlink()
    ctl('daemon-reload',check=False)
    if clean!=original: atomic(sidebar,clean)
    for p in (page,js):
        if p.exists(): p.unlink()
    print('PiShield removed. Pi-hole DNS and settings unchanged. Browser labels and history, local state, and backups retained in /var/backups/pishield.')
    sys.exit(0)
for p in [root/'scripts/lua/header_authenticated.lp',root/'scripts/lua/footer.lp',root/'scripts/lua/header.lp']:
    if not p.is_file(): sys.exit(f'Missing native template: {p}. No changes made.')
if clean.count(anchor)!=1: sys.exit('Sidebar layout differs from expected version. No changes made.')
if 'data-apiurl' not in read(root/'scripts/lua/header_authenticated.lp'): sys.exit('Native API binding not found. No changes made.')
if 'csrf-token' not in read(root/'scripts/lua/header.lp'): sys.exit('Native CSRF binding not found. No changes made.')
backup.mkdir(mode=0o700,parents=True,exist_ok=True)
backup.chmod(0o700)
state.mkdir(mode=0o700,parents=True,exist_ok=True)
state.chmod(0o700)
collectorpath.parent.mkdir(mode=0o755,parents=True,exist_ok=True)
unit_status={name:(is_enabled(name),is_active(name)) for name in timers}
b=Path(tempfile.mkdtemp(prefix=time.strftime('%Y%m%d-%H%M%S-'),dir=backup))
shutil.copy2(sidebar,b/'sidebar.lp')
for p in (page,js,*extra):
    if p.exists(): shutil.copy2(p,b/p.name)
idx=clean.index(anchor); line=clean.rfind('\n',0,idx)+1
patched=clean[:line]+links+clean[line:]
try:
    for name in timers+services: ctl('stop',name,check=False)
    atomic(page,html);atomic(js,script)
    for p,data in extra.items():
        if p==systempage and p.exists(): continue
        atomic(p,data)
    atomic(sidebar,patched)
    ctl('daemon-reload')
    ctl('enable','--now',*timers)
    ctl('start','--no-block','pishield-backup.service','pishield-collect.service')
except BaseException:
    for name in timers: ctl('disable','--now',name,check=False)
    for name in services: ctl('stop',name,check=False)
    atomic(sidebar,original)
    for p in (page,js,*extra):
        old=b/p.name
        if old.exists(): atomic(p,read(old))
        elif p.exists(): p.unlink()
    ctl('daemon-reload',check=False)
    for name,(enabled,active) in unit_status.items():
        if enabled: ctl('enable',name,check=False)
        if active: ctl('start',name,check=False)
    raise
print('PiShield v0.3 installed. Refresh Pi-hole and open Security overview in the sidebar.')
print('Backup:',b)
print('Discovery and backup timers enabled; inspect their service logs if no sample appears. Rerun installer after Pi-hole updates if necessary.')
PY
